//! Expected bytes are independent fixtures, not output generated by our encoder.
use meedee::codecs::{encode, DecodeItem, Decoder, DiagnosticKind};
use meedee::messages::*;

#[test]
fn shared_wire_vectors_match_values_and_all_two_part_feeds() {
    for line in include_str!("fixtures/midi1.txt").lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let (fields, wire) = line.split_once('|').unwrap();
        let mut fields = fields.split_whitespace();
        let name = fields.next().unwrap();
        let fields: Vec<_> = fields.collect();
        let bytes: Vec<_> = wire
            .split_whitespace()
            .map(|v| u8::from_str_radix(v, 16).unwrap())
            .collect();
        let message = fixture_message(name, &fields);
        assert_eq!(encode(&message).unwrap(), bytes, "{line}");
        for split in 0..=bytes.len() {
            let mut decoder = Decoder::default();
            let mut actual = decoder.feed(&bytes[..split]);
            actual.extend(decoder.feed(&bytes[split..]));
            assert_eq!(
                actual,
                vec![DecodeItem::Message(message.clone())],
                "{line}, split {split}"
            );
            assert!(decoder.finish().is_empty());
        }
    }
}

#[test]
fn feed_partitions_preserve_running_status_realtime_and_error_order() {
    // Includes a missing velocity, an interrupted SysEx and reserved real-time.
    let bytes = [0x90, 60, 0xf8, 100, 61, 0xf9, 0xf0, 1, 0xfa, 0x80, 60, 0];
    let mut whole = Decoder::default();
    let mut expected = whole.feed(&bytes);
    expected.extend(whole.finish());
    for mask in 0..1 << (bytes.len() - 1) {
        let mut decoder = Decoder::default();
        let mut actual = Vec::new();
        let mut start = 0;
        for end in 1..=bytes.len() {
            if end == bytes.len() || mask & (1 << (end - 1)) != 0 {
                actual.extend(decoder.feed(&bytes[start..end]));
                start = end;
            }
        }
        actual.extend(decoder.finish());
        assert_eq!(actual, expected);
    }
}

#[test]
fn all_channel_statuses_and_data_boundaries_round_trip_without_normalization() {
    for status in 0x80..=0xef {
        for a in 0..=127 {
            for b in [0, 127] {
                let mut wire = vec![status, a];
                if !(0xc0..=0xdf).contains(&status) {
                    wire.push(b);
                }
                let mut decoder = Decoder::default();
                let items: [DecodeItem; 1] = decoder.feed(&wire).try_into().unwrap();
                let [DecodeItem::Message(message)] = items else {
                    panic!("valid wire message was not decoded");
                };
                assert_eq!(encode(&message).unwrap(), wire);
            }
        }
    }
}

#[test]
fn arbitrary_byte_pairs_and_state_transitions_never_panic() {
    for a in 0..=255 {
        for b in 0..=255 {
            let mut decoder = Decoder::new(1).unwrap();
            decoder.feed(&[0xf0, 1, a, b, 0x90, 60, 1, 0xf7]);
            decoder.finish();
            decoder.reset();
        }
    }
}

#[test]
fn sysex_limit_reports_once_and_releases_state_before_recovery() {
    let mut decoder = Decoder::new(2).unwrap();
    assert!(decoder.feed(&[0xf0, 1, 2]).is_empty());
    let items = decoder.feed(&[3, 4, 0xf8, 5, 0xf7, 0x90, 60, 0]);
    assert!(
        matches!(&items[0], DecodeItem::Diagnostic(d) if d.kind == DiagnosticKind::SysExTooLarge && d.offset == 3)
    );
    assert_eq!(items.len(), 3);
    assert_eq!(
        items[1],
        DecodeItem::Message(AnyMessage::TimingClock(TimingClock::new().unwrap()))
    );
    assert_eq!(
        items[2],
        DecodeItem::Message(AnyMessage::NoteOn(
            NoteOn::new(60)
                .and_then(|m| m.with_velocity(0))
                .and_then(|m| m.with_channel(1))
                .unwrap()
        ))
    );
    assert!(decoder.finish().is_empty());
    assert!(Decoder::new(0).is_err());
}

fn fixture_message(name: &str, fields: &[&str]) -> AnyMessage {
    if name == "SysEx" {
        return AnyMessage::SysEx(
            SysEx::new(
                fields
                    .iter()
                    .map(|v| u8::from_str_radix(v, 16).unwrap())
                    .collect(),
            )
            .unwrap(),
        );
    }
    let values: Vec<i64> = fields.iter().map(|v| v.parse().unwrap()).collect();
    match name {
        "NoteOn" => AnyMessage::NoteOn(
            NoteOn::new(values[1])
                .unwrap()
                .with_velocity(values[2])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "NoteOff" => AnyMessage::NoteOff(
            NoteOff::new(values[1])
                .unwrap()
                .with_velocity(values[2])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "PolyPressure" => AnyMessage::PolyPressure(
            PolyPressure::new(values[1])
                .unwrap()
                .with_pressure(values[2])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "ControlChange" => AnyMessage::ControlChange(
            ControlChange::new(values[1], values[2])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "ProgramChange" => AnyMessage::ProgramChange(
            ProgramChange::new(values[1])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "ChannelPressure" => AnyMessage::ChannelPressure(
            ChannelPressure::new()
                .unwrap()
                .with_pressure(values[1])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        "PitchBend" => AnyMessage::PitchBend(
            PitchBend::new()
                .unwrap()
                .with_value(values[1])
                .unwrap()
                .with_channel(values[0])
                .unwrap(),
        ),
        _ => {
            macro_rules! construct {
        ($($name:ident ($($index:literal),*)),*) => {
            match name {
                $(stringify!($name) => AnyMessage::$name($name::new($(values[$index]),*).unwrap()),)*
                _ => panic!("unrecognized fixture message {name}"),
            }
        };
    }
            construct! {
                QuarterFrame(0,1),
                SongPosition(0), SongSelect(0), TuneRequest(), TimingClock(), Start(),
                Continue(), Stop(), ActiveSensing(), SystemReset()
            }
        }
    }
}

#[test]
fn defaults_require_channel_resolution_and_transposition_clamps() {
    let note = NoteOn::new(60).unwrap();
    assert_eq!(note.channel(), None);
    assert_eq!(note.velocity(), 90);
    assert!(note.encode().is_err());
    let note = note.with_channel(3).unwrap();
    assert_eq!(note.encode().unwrap(), [0x92, 60, 90]);
    let high = note.clone().transpose(i64::MAX);
    assert_eq!(high.encode().unwrap(), [0x92, 127, 90]);
    assert_eq!(note.clone().transpose(i64::MIN).note(), 0);
    assert_eq!(note.clone().without_channel().channel(), None);
    assert!(note.without_channel().encode().is_err());
    let release = NoteOff::new(60).unwrap().with_channel(3).unwrap();
    assert_eq!(release.transpose(12).encode().unwrap(), [0x82, 72, 0]);
    assert_eq!(PitchBend::new().unwrap().value(), 0);
    assert_eq!(ChannelPressure::new().unwrap().pressure(), 0);
    assert_eq!(PolyPressure::new(60).unwrap().pressure(), 0);
}

#[test]
fn commands_resolve_channels_before_expansion_and_builders_validate_ranges() {
    let command = ParameterSet::new(0, 128).unwrap();
    assert_eq!(command.resolution(), 14);
    assert!(command.expand().is_err());
    assert!(command.clone().with_resolution(7).is_err());
    assert!(command.clone().with_resolution(8).is_err());
    let messages = command.with_channel(2).unwrap().expand().unwrap();
    assert!(messages.iter().all(|m| m.encode().unwrap()[0] == 0xb1));
    let bank = meedee::messages::ProgramChange::new(34)
        .and_then(|m| m.with_bank(0, 0))
        .unwrap();
    assert!(bank.expand().is_err());
    let bytes: Vec<_> = bank
        .with_channel(2)
        .unwrap()
        .expand()
        .unwrap()
        .iter()
        .flat_map(|m| m.encode().unwrap())
        .collect();
    assert_eq!(bytes, [0xb1, 0, 0, 0xb1, 32, 0, 0xc1, 33]);
    assert!(ParameterSet::new(0, 127)
        .unwrap()
        .with_resolution(7)
        .unwrap()
        .with_value(128)
        .is_err());
}
